Section ENTRY.
  Variable X : pctx.
  Abbreviation ra := (c_ra X). Abbreviation sp := (c_sp X). Abbreviation gp := (c_gp X). Abbreviation tp := (c_tp X).
  Abbreviation s0 := (c_s0 X). Abbreviation s1 := (c_s1 X). Abbreviation s2 := (c_s2 X). Abbreviation s3 := (c_s3 X).
  Abbreviation s4 := (c_s4 X). Abbreviation s5 := (c_s5 X). Abbreviation s6 := (c_s6 X). Abbreviation s7 := (c_s7 X).
  Abbreviation s8 := (c_s8 X). Abbreviation s9 := (c_s9 X). Abbreviation s10 := (c_s10 X). Abbreviation s11 := (c_s11 X).
  Abbreviation F := (c_F X). Abbreviation fc := (c_fc X).
  Abbreviation LB0 := (c_LB0 X). Abbreviation LF := (c_LF X). Abbreviation P := (c_P X). Abbreviation E := (c_E X).
  Abbreviation lo := (c_lo X). Abbreviation B := (c_B X). Abbreviation shi := (c_shi X). Abbreviation pad7 := (c_pad7 X). Abbreviation pad2 := (c_pad2 X).
  Abbreviation p0 := (c_p0 X). Abbreviation R := (c_R X). Abbreviation bs := (c_bs X). Abbreviation mb := (c_mb X).
  Abbreviation d0 := (c_d0 X). Abbreviation sE := (c_sE X). Abbreviation m0 := (c_m0 X). Abbreviation mo0 := (c_mo0 X).
  Abbreviation spa := (c_spa X). Abbreviation ff := (c_ff X). Abbreviation fp := (c_fp X). Abbreviation gap := (c_gap X).

  Definition p1 : Z := p0 + Z.of_nat (length bs).

  (* [comment removed for export] *)
  Definition pctx_ok : Prop :=
    put_static H MX CX sp tp P E lo B shi p0 R bs
    /\ (spa = bv_unsigned sp + -288 \/ spa = bv_unsigned sp + -304) /\ spa mod 32 = 0
    /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184)
    /\ fresh_frame H LF 1 ff fp
    /\ aobj LB0 LF P PARSER_SIZE /\ aobj LB0 LF E 24 /\ aobj LB0 LF p0 (Z.of_nat (length bs))
    /\ (length LF + 5 < AFS_MAXLIVE)%nat (* [comment removed for export] *) /\ (length LF + 1 < AFS7_MAXLIVE)%nat
    /\ bv_unsigned ra mod 2 = 0 /\ ps_LBn d0 = []
    /\ (exists s00, as_RHEAP H s00 LB0 m0) /\ as_RFS H LF m0
    /\ bv_unsigned mb <= 1.                                            (* [comment removed for export] *)

  Hypothesis XOK : pctx_ok.

  (* [comment removed for export] *)
  Local Ltac open_X :=
    pose proof XOK as (STAT & SPA & SPA32 & GSZ & FF & AOP & AOE & AOW & LFN & LF7 & RA2 & LBN0 & RH0 & RF0 & MBLE).

