(* [comment removed for export] *)
Definition bp_frame (m : mem) (p : Z) : Prop :=
  exists j0 j128 j152 ja j48 jb j80 jc j112,
       rw_cells bsegs m spa (bp_locals E P p0 ff j0 j128 j152 p)
    /\ rw_cells bsegs m (spa + 184) gap
    /\ rw_cells bsegs m (bv_unsigned sp + -104) (bp_saves s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m ff (bp_ffr spa fp ja j48 jb j80 jc j112)
    /\ rw_cells bsegs m (sh ff) (bp_sh F8b F8b F8b)
    /\ rw_cells bsegs m fp [C1 (b8 1)].

(* [comment removed for export] *)
Definition bp_side (m : mem) : Prop :=
  as_RFS H ((1, ff, fp) :: LF) m /\ ACONST m /\ stack0 m lo shi
  /\ accessible m P PARSER_SIZE /\ accessible m E 24 /\ accessible m p0 (Z.of_nat (length bs))
  /\ shvis m E (E + 24) /\ shvis m p0 (p0 + Z.of_nat (length bs)).

(* [comment removed for export] *)
Definition bp_fsw : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16)]%Z.

(* [comment removed for export] *)
Definition bput_inv (s : as_St H) (d : pst) (m : mem) (p : Z) (E' : ecv) (XS : list (Z * Z)) : Prop :=
  mem_inv bsegs m /\ stk bsegs m lo spa
  /\ (exists errv, rw_cells bsegs m (errno_addr tp) [C4 errv]) /\ as_rauxv_ok H m B
  /\ as_RHEAP H s (ps_LBn d ++ LB0) m
  /\ bp_frame m p /\ bp_side m
  /\ rw_cells bsegs m P (ParserCoreCells (ps_c d) pad7 pad2)
  /\ rw_cells bsegs m E (ErrCodeCells E') /\ ec_ok E'
  /\ rw_cells bsegs m (P + 240) [C1 (ps_rdi d)] /\ AHttpCat m (ps_g d) /\ (AFieldTabZero m \/ FT m)
  /\ PutU P p0 bs mb d m /\ HdrOwnA (ps_LBn d ++ LB0) m (ps_h d)
  /\ PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0) d /\ PutB MX CX MA LB0 p0 R d p
  /\ Forall (fs_scratch H LF) XS /\ Forall (fun iv => In iv XS) bp_fsw /\ xpres H LB0 (bv_unsigned sp) (put_X P E (ps_L d0) (ps_es d0) ++ XS) m0 m
  /\ al_ok H s (ps_A d) MA MR /\ ps_A d0 <= ps_A d
  /\ p0 <= p <= p1.

