Lemma wg_disjoint : forall W A n, Forall wg W -> A + n <= 0x12a180 -> disjoint_from W A n.
Proof.
  open_X.
  intros W A n FW HA. apply disjoint_from_Forall. eapply Forall_impl; [| exact FW]. intros iv WG. left. pose proof (wg_num iv WG) as (K & _). lia.
Qed.
Lemma wg_disjoint_ft : forall W, Forall wg W -> disjoint_from W AG_FIELD_TABLE 3456.
Proof.
  open_X.
  intros W FW. apply disjoint_from_Forall. eapply Forall_impl; [| exact FW]. intros iv WG. pose proof (wg_num iv WG) as (_ & K & _). exact K.
Qed.
Lemma wg_disjoint_errno : forall W, Forall wg W -> disjoint_from W AERRNO 4.
