(* [comment removed for export] *)
Lemma keep_hdr : forall W m m' s mx d, Forall wg W -> munch W m m' -> wmono bsegs m m' ->
  as_RHEAP H s (ps_LBn d ++ LB0) mx -> PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0) d ->
  HdrOwnA (ps_LBn d ++ LB0) m (ps_h d) -> HdrOwnA (ps_LBn d ++ LB0) m' (ps_h d).
Proof.
  open_X.
  intros W m m' s mx d FW MU WM RH L (OM & OT & RM & RT).
  pose proof L as (PCOK & OWN & MOWN & NEW & NEWB & OFP & OFE & _). destruct OFP as (_ & _ & [HTP HMP]). destruct OFE as (_ & _ & [HTE HME]).
  assert (K : forall ptr len, ASvOwn (ps_LBn d ++ LB0) m ptr len ->
              (len <> 0 -> P + PARSER_SIZE <= ptr \/ ptr + len <= P) -> (len <> 0 -> E + 24 <= ptr \/ ptr + len <= E) ->
              ASvOwn (ps_LBn d ++ LB0) m' ptr len).
  { intros ptr len [Z0|(L1 & p & cs & IN & C & AD)] SP1 SE1; [left; exact Z0| right].
    destruct (wg_sep_blk W s (ps_LBn d) mx p ptr len FW RH IN (SP1 ltac:(lia)) (SE1 ltac:(lia))) as [D1 D2].
    split; [exact L1|]. exists p, cs. split; [exact IN|]. split.
    - eapply rw_cells_transport; [exact C| exact MU| exact WM|]. cbn [cells_size csize]. rewrite Nat.add_0_r, Z2Nat.id by lia. exact D1.
    - eapply addressable_transport; [exact AD| exact MU| exact WM| exact D2]. }
  split; [| split; [| split; [exact RM| exact RT]]].
  - apply K; [exact OM| exact HMP| exact HME].
  - apply K; [exact OT| exact HTP| exact HTE].
Qed.

Lemma keep_ft : forall W m m', Forall wg W -> munch W m m' -> wmono bsegs m m' -> (AFieldTabZero m \/ FT m) -> (AFieldTabZero m' \/ FT m').
Proof. intros W m m' FW MU WM FTS. eapply FTState_transport; [exact FTS| exact MU| exact WM| apply wg_disjoint_ft; exact FW]. Qed.

(* [comment removed for export] *)
Lemma keep_cat : forall W m m' g, Forall wg W -> Forall (fun iv : Z * Z => AG_HTTP_CAT + 64 <= fst iv \/ snd iv <= AG_HTTP_CAT) W ->
